-- Batch 1 UA: amazon-q-developer, dall-e-3, v0-by-vercel, manus, devin, chatgpt, claude, grok, deepseek, cursor

UPDATE tools SET
  best_for         = $d1u$Розробники в екосистемі AWS$d1u$,
  description      = $d1u$Amazon Q Developer — AI-асистент для коду, глибоко інтегрований в екосистему AWS. Пропонує автодоповнення коду, генерацію функцій і аналіз безпеки прямо в IDE.$d1u$,
  description_long = $dl1u$Amazon Q Developer розроблений для команд, що інтенсивно працюють з AWS. Надає контекстні підказки коду, може генерувати повні Lambda-функції та автоматично аналізує код на вразливості. Примітка: Amazon переводить користувачів на Kiro як наступника цього інструменту.$dl1u$,
  pros = ARRAY['Нативна інтеграція з AWS', 'Автоматичний аналіз безпеки', 'Генерація Lambda-коду', 'Безкоштовно в AWS Free Tier'],
  cons = ARRAY['Обмежений поза екосистемою AWS', 'Міграція до Kiro в процесі', 'Менш універсальний за GitHub Copilot']
WHERE slug = 'amazon-q-developer' AND lang = 'ua';

UPDATE tools SET
  best_for         = $d2u$Створення зображень з детальних текстових описів$d2u$,
  description      = $d2u$DALL-E 3 — модель генерації зображень від OpenAI, відома точним дотриманням текстових інструкцій. Інтегрована безпосередньо в ChatGPT та API OpenAI.$d2u$,
  description_long = $dl2u$DALL-E 3 вирізняється здатністю інтерпретувати складні та детальні промпти, створюючи зображення, що точно відповідають опису користувача. На відміну від попередніх версій, розуміє абстрактні концепції та може відображати текст всередині зображень. Доступна через ChatGPT Plus та API — ідеальна для дизайнерів, контент-мейкерів і розробників, яким потрібні зображення професійної якості.$dl2u$,
  pros = ARRAY['Відмінне дотримання інструкцій', 'Інтегровано в ChatGPT', 'Підтримка тексту в зображеннях', 'API доступне'],
  cons = ARRAY['Сувора модерація контенту', 'Без гранульованого контролю стилю', 'Висока вартість через API']
WHERE slug = 'dall-e-3' AND lang = 'ua';

UPDATE tools SET
  best_for         = $d3u$Швидка генерація UI-компонентів на React$d3u$,
  description      = $d3u$v0 від Vercel — AI-інструмент, що генерує React і Tailwind CSS UI-компоненти з текстових описів та дозволяє ітерувати дизайн візуально без ручного кодування.$d3u$,
  description_long = $dl3u$v0 орієнтований на фронтенд-розробників і дизайнерів, які хочуть швидко прототипувати інтерфейси. Модель генерує готовий для копіювання React-код з використанням Shadcn/UI і Tailwind CSS. Можна описати компонент природною мовою, побачити превʼю в реальному часі та ітерувати з новими інструкціями. Інтегрується безпосередньо з екосистемою Vercel для швидких деплойментів.$dl3u$,
  pros = ARRAY['Функціональний генератор React-коду', 'Превʼю в реальному часі', 'Інтеграція з Vercel', 'Використовує Shadcn/UI і Tailwind'],
  cons = ARRAY['Обмежено компонентами React/Next.js', 'Обмежені безкоштовні кредити', 'Потрібна ручна перевірка коду']
WHERE slug = 'v0-by-vercel' AND lang = 'ua';

UPDATE tools SET
