  description      = $d4u$Manus — автономний AI-агент, здатний виконувати багатоетапні завдання в браузері, включаючи дослідження, аналіз даних і підготовку звітів без постійного нагляду.$d4u$,
  description_long = $dl4u$Manus відрізняється від традиційних чат-асистентів здатністю діяти автономно: може переміщатися в мережі, виконувати код, аналізувати файли та завершувати складні робочі процеси. Особливо корисний для конкурентної розвідки, підготовки звітів та автоматизації завдань, які зазвичай потребують кількох інструментів і значного часу.$dl4u$,
  pros = ARRAY['Справжня автономія в складних завданнях', 'Самостійно переміщається в мережі', 'Виконує код і аналізує дані', 'Ідеальний для глибоких досліджень'],
  cons = ARRAY['Обмежений доступ — список очікування', 'Може помилятися без нагляду', 'Висока вартість при інтенсивному використанні']
WHERE slug = 'manus' AND lang = 'ua';

UPDATE tools SET
