  description      = $d5u$Devin — перший автономний агент для розробки ПЗ, що планує та виконує повні завдання програмування. З травня 2026 доступний за $20/місяць замість $500.$d5u$,
  description_long = $dl5u$Розроблений Cognition AI, Devin може вирішувати тікети GitHub, писати та виконувати код, виправляти помилки та здійснювати деплойменти автономно. Працює у власному пісочному середовищі з доступом до браузера, терміналу та редактора коду. У травні 2026 Cognition знизив ціну з $500 до $20/місяць, зробивши його доступним для індивідуальних розробників.$dl5u$,
  pros = ARRAY['Повністю автономний агент', 'Ціна знижена до $20/місяць', 'Доступ до терміналу, браузера та редактора', 'Вирішує тікети GitHub'],
  cons = ARRAY['Потребує нагляду для критичних завдань', 'Може генерувати помилки у складному коді', 'Ще в ранній стадії розробки']
WHERE slug = 'devin' AND lang = 'ua';

UPDATE tools SET
  best_for         = $d6u$Загальний AI-асистент для написання текстів, коду та аналізу$d6u$,
  description      = $d6u$ChatGPT — AI-асистент OpenAI на основі моделей GPT. GPT-5.5, тепер модель за замовчуванням, скорочує галюцинації на 52% і доступна в усіх тарифах.$d6u$,
  description_long = $dl6u$ChatGPT — найбільш використовуваний у світі розмовний AI-асистент. З появою GPT-5.5 як моделі за замовчуванням у травні 2026 року користувачі отримують точніші відповіді з 52% менше галюцинацій порівняно з GPT-4o. Підтримує текст, зображення, код, пошук в інтернеті в реальному часі та пам'ять розмов. Доступний у безкоштовному, Plus та Team тарифах.$dl6u$,
  pros = ARRAY['GPT-5.5 доступна в усіх тарифах', 'Пам''ять розмов', 'Пошук в мережі в реальному часі', 'Вбудовані інструменти: код, зображення, файли'],
  cons = ARRAY['Може галюцинувати для специфічних даних', 'Безкоштовний тариф з обмеженнями', 'Не ідеальний для дуже технічних завдань без контексту']
WHERE slug = 'chatgpt' AND lang = 'ua';

UPDATE tools SET
  best_for         = $d7u$Складне написання текстів, аналіз документів і безпечний код$d7u$,
  description      = $d7u$Claude — AI-асистент від Anthropic, розроблений з акцентом на безпеку, глибоке міркування та генерацію якісного тексту. Родина Claude 4 включає Opus, Sonnet і Haiku.$d7u$,
  description_long = $dl7u$Claude вирізняється здатністю підтримувати довгі розмови з високою зв'язністю, аналізувати великі документи та створювати текст, що звучить автентично і нюансовано. З Claude 4 Opus користувачі отримують доступ до найсучаснішої моделі Anthropic для складних завдань міркування, кодування та аналізу. Особливо цінується в професійних та академічних середовищах.$dl7u$,
  pros = ARRAY['Висока зв''язність у довгих розмовах', 'Аналіз великих документів', 'Акцент на безпеку та етику', 'Claude 4 Opus для складних завдань'],
  cons = ARRAY['Немає нативного пошуку в мережі в деяких тарифах', 'Менше сторонніх інтеграцій ніж у ChatGPT', 'Тариф Pro дорожчий']
WHERE slug = 'claude' AND lang = 'ua';

UPDATE tools SET
