  description      = $d9u$DeepSeek — розроблена в Китаї мовна модель з відкритим кодом, що конкурує з найкращими пропрієтарними моделями в бенчмарках з міркування, математики та кодування.$d9u$,
  description_long = $dl9u$DeepSeek R1 та його варіанти здивували AI-спільноту, пропонуючи продуктивність, порівнянну з GPT-4o та Claude 3.5, але безкоштовно та з відкритим кодом. Особливо сильний у математиці, науці та програмуванні. Як open source може запускатися локально або розгортатися на власній інфраструктурі. API значно дешевше ніж у конкурентів.$dl9u$,
  pros = ARRAY['Відкритий код і безкоштовно', 'Відмінний у математиці та кодуванні', 'Дуже дешевий API', 'Може запускатися локально'],
  cons = ARRAY['Проблеми з конфіденційністю — дані на китайських серверах', 'Менш відполірований інтерфейс ніж у ChatGPT', 'Рідші оновлення']
WHERE slug = 'deepseek' AND lang = 'ua';

UPDATE tools SET
