  description_long = $dl10u$Cursor виходить за межі автодоповнення: можна описати зміни природною мовою і редактор застосує їх безпосередньо в коді. У режимі Composer можна створювати цілі файли або рефакторити кілька файлів одночасно. Підтримує провідні AI-моделі (GPT-4, Claude тощо) і став улюбленим інструментом багатьох розробників для прискорення розробки. Сумісний з розширеннями VS Code.$dl10u$,
  pros = ARRAY['AI нативно інтегрований в редактор', 'Режим Composer для змін у кількох файлах', 'Сумісний з розширеннями VS Code', 'Підтримує кілька AI-моделей'],
  cons = ARRAY['Безкоштовна версія з обмеженнями використання', 'Може пропонувати хибний код без достатнього контексту', 'Потрібен хороший опис проблеми']
WHERE slug = 'cursor' AND lang = 'ua';
